                        <?php
                        if ($main_content) :
                        ?>
                            <p><?php echo wp_kses_post(wp_trim_words($main_content, 15, '...')); ?></p>
                        <?php endif; ?>

                        <?php if ($tagline) : ?>
                            <p class="post-tagline">
                                <?php echo esc_html($tagline) ?>
                            </p>
                        <?php endif; ?>

